"""The plugin registry."""


class Registry:
    """Maps names to plugin factories."""

    def __init__(self):
        self._factories = {}

    def register(self, name, factory):
        """Add a factory under a name; a repeated name is an error."""
        if name in self._factories:
            raise ValueError(f"plugin {name!r} is already registered; the first registration is kept")
        self._factories[name] = factory

    def get(self, name):
        """Build and return the plugin called name."""
        return self._factories[name]()

    def names(self):
        """Return the registered names, sorted."""
        return sorted(self._factories)
